desk.mjs
import {readFileSync,writeFileSync} from 'node:fs';
const [file,command,code]=process.argv.slice(2);
const load=path=>JSON.parse(readFileSync(path,'utf8')).map(row=>({...row,flagged:Boolean(row.flagged)}));
const save=(path,rows)=>writeFileSync(path,JSON.stringify(rows.map(({code,title})=>({code,title}))));
const rows=load(file);
if(command==='mark'){const item=rows.find(r=>r.code===code);if(!item)throw Error('Unknown card');item.flagged=true;save(file,rows);console.log(item.code)}
else if(command==='list')console.log(JSON.stringify(rows.filter(x=>x.flagged).map(x=>x.code)));
else throw Error('Unknown operation');
